import{_ as t,o as a,c as r,ag as d}from"./chunks/framework.C9sp7nFj.js";const _=JSON.parse('{"title":"ReceiveWObj 设置工件接收状态","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/14. 传送带跟随指令/ReceiveWObj.md","filePath":"3. 指令/14. 传送带跟随指令/ReceiveWObj.md","lastUpdated":1778862643000}'),o={name:"3. 指令/14. 传送带跟随指令/ReceiveWObj.md"};function i(c,e,n,h,b,l){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="receivewobj-设置工件接收状态" tabindex="-1">ReceiveWObj 设置工件接收状态 <a class="header-anchor" href="#receivewobj-设置工件接收状态" aria-label="Permalink to &quot;ReceiveWObj 设置工件接收状态&quot;">​</a></h1><p>该指令为设置工件数据的接收状态指令，通过组合使用该指令可以让机器人系统在某一段轨迹内不接收视觉或 run 程序中发来的工件位置信息，避免出现误跟随的情况，满足不同的现场工艺。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>ReceiveWObj(Coord, enableSts)</p><p>ReceiveWObj(坐标系, 使能接收状态)</p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>Coord</td><td>SYNCOORD 变量</td><td>当前工件位置信息所参考的动坐标系，需与传送带配置界面中启用的动坐标系一致</td><td>必填</td></tr><tr><td>enableSts</td><td>enum</td><td>使能机器人系统对工件位置信息的接收状态：<br>OFF—关闭接收<br>ON—开启接收</td><td>必填</td></tr></tbody></table>',8)])])}const p=t(o,[["render",i]]);export{_ as __pageData,p as default};
